func TestUbuntuAPICvss3Severity(t *testing.T) {
	vuln := VulnInfo{CveContents: NewCveContents(
		CveContent{Type: Ubuntu, Cvss3Severity: "NEGLIGIBLE"},
		CveContent{Type: UbuntuAPI, Cvss3Severity: "HIGH"},
	)}
	if got, want := vuln.Cvss3Scores(), []CveContentCvss{
		{Type: Ubuntu, Value: Cvss{Type: CVSS3, Score: 3.9, CalculatedBySeverity: true, Severity: "NEGLIGIBLE"}},
		{Type: UbuntuAPI, Value: Cvss{Type: CVSS3, Score: 8.9, CalculatedBySeverity: true, Severity: "HIGH"}},
	}; !reflect.DeepEqual(got, want) {
		t.Errorf("Cvss3Scores() = %v, want %v", got, want)
	}
	if got := vuln.MaxCvss3Score(); got.Type != UbuntuAPI || got.Value.Score != 8.9 {
		t.Errorf("MaxCvss3Score() = %v, want UbuntuAPI score 8.9", got)
	}
	if got := (Cvss{Severity: "NEGLIGIBLE"}).SeverityToCvssScoreRange(); got != "0.1-3.9" {
		t.Errorf("SeverityToCvssScoreRange(NEGLIGIBLE) = %q, want 0.1-3.9", got)
	}
}

